"""Shared AgentWhite visual identity for local UI pages."""

LOGO_DATA_URI = "data:image/webp;base64,"

COMMON_CSS = r"""
:root{--aw-bg:#020807;--aw-bg2:#04110d;--aw-panel:rgba(4,18,14,.90);--aw-panel2:rgba(7,28,21,.92);--aw-line:#0d5d43;--aw-line2:#138c62;--aw-text:#eafff5;--aw-muted:#79a997;--aw-green:#00f59a;--aw-cyan:#25dfff;--aw-blue:#3ea8ff;--aw-red:#ff4b5f;--aw-amber:#ffd45b;--aw-shadow:0 0 0 1px rgba(0,245,154,.08),0 18px 55px rgba(0,0,0,.42)}
*{box-sizing:border-box}html,body{min-height:100%;margin:0}body{color:var(--aw-text);font:13px/1.45 Inter,ui-monospace,SFMono-Regular,Consolas,"Liberation Mono",monospace;background:radial-gradient(circle at 74% 18%,rgba(31,134,255,.12),transparent 28%),radial-gradient(circle at 18% 72%,rgba(0,245,154,.10),transparent 30%),linear-gradient(135deg,#010403 0,#02100c 45%,#010706 100%);overflow-x:hidden}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.18;background-image:repeating-linear-gradient(90deg,transparent 0 39px,rgba(0,245,154,.035) 40px),repeating-linear-gradient(0deg,transparent 0 39px,rgba(0,245,154,.025) 40px),linear-gradient(180deg,rgba(0,255,160,.04),transparent 22%,transparent 78%,rgba(0,130,255,.04))}body:after{content:"01001010   10110010   00110101   11001001   01010110   00101101   11100010   01001010   10110010   00110101   11001001";position:fixed;inset:0;pointer-events:none;color:rgba(0,255,128,.055);font-size:10px;letter-spacing:11px;line-height:24px;white-space:pre-wrap;word-break:break-all;transform:rotate(-1deg) scale(1.04);filter:blur(.1px)}
a{color:inherit}button,input,select{font:inherit}.aw-app{position:relative;z-index:1;display:grid;grid-template-columns:196px minmax(0,1fr);min-height:100vh}.aw-sidebar{position:sticky;top:0;height:100vh;padding:14px 12px;border-right:1px solid rgba(0,245,154,.24);background:linear-gradient(180deg,rgba(2,13,10,.97),rgba(2,8,7,.94));box-shadow:8px 0 38px rgba(0,0,0,.34)}.aw-brand{display:flex;gap:10px;align-items:center;padding:4px 5px 14px;border-bottom:1px solid rgba(0,245,154,.16)}.aw-logo{width:58px;height:58px;object-fit:contain;filter:drop-shadow(0 0 10px rgba(42,190,255,.44))}.aw-wordmark{font-size:18px;font-weight:800;letter-spacing:3px}.aw-wordmark span{color:#bfefff;text-shadow:0 0 14px rgba(37,223,255,.7)}.aw-tagline{font-size:8px;letter-spacing:1.7px;color:var(--aw-muted);margin-top:3px}.aw-nav{display:flex;flex-direction:column;gap:5px;padding-top:14px}.aw-nav a{display:flex;gap:9px;align-items:center;padding:10px 10px;border:1px solid transparent;border-radius:8px;text-decoration:none;color:#b4d8ca;transition:.18s}.aw-nav a:hover,.aw-nav a.active{color:white;border-color:rgba(0,245,154,.34);background:linear-gradient(90deg,rgba(0,245,154,.16),rgba(19,140,98,.04));box-shadow:inset 3px 0 0 var(--aw-green),0 0 20px rgba(0,245,154,.07)}.aw-nav .ico{width:22px;text-align:center;color:var(--aw-green);font-size:15px}.aw-sidebar-foot{position:absolute;left:12px;right:12px;bottom:16px;padding:10px;border-top:1px solid rgba(0,245,154,.18);color:var(--aw-muted);font-size:10px}.aw-main{min-width:0;padding:12px 14px 24px}.aw-topbar{display:flex;gap:12px;align-items:center;padding:8px 10px 12px}.aw-search{flex:1;max-width:720px;position:relative}.aw-search input{width:100%;padding:11px 14px 11px 38px;border:1px solid rgba(37,223,255,.24);border-radius:8px;background:rgba(1,9,8,.78);color:var(--aw-text);outline:none;box-shadow:inset 0 0 25px rgba(0,0,0,.35)}.aw-search:before{content:"⌕";position:absolute;left:13px;top:7px;color:var(--aw-cyan);font-size:21px}.aw-topstatus{margin-left:auto;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.aw-pill,.aw-badge{display:inline-flex;gap:6px;align-items:center;border:1px solid rgba(0,245,154,.22);border-radius:999px;padding:6px 9px;background:rgba(2,14,11,.72);color:var(--aw-muted);font-size:10px;text-transform:uppercase;letter-spacing:.7px}.aw-pill.ok,.aw-badge.ok{color:var(--aw-green);border-color:rgba(0,245,154,.42)}.aw-pill:before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;box-shadow:0 0 10px currentColor}.aw-panel{position:relative;background:linear-gradient(180deg,var(--aw-panel2),var(--aw-panel));border:1px solid rgba(0,245,154,.28);border-radius:10px;box-shadow:var(--aw-shadow);overflow:hidden}.aw-panel:before{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(0,245,154,.025),transparent 18%,transparent 82%,rgba(37,223,255,.025))}.aw-panel-head{position:relative;z-index:1;display:flex;gap:8px;align-items:center;min-height:42px;padding:9px 12px;border-bottom:1px solid rgba(0,245,154,.20);background:linear-gradient(90deg,rgba(0,245,154,.035),transparent)}.aw-panel-head h2,.aw-panel-head strong{margin:0;font-size:12px;letter-spacing:1px}.aw-panel-body{position:relative;z-index:1;padding:10px}.aw-card{border:1px solid rgba(0,245,154,.18);border-radius:8px;background:rgba(2,12,10,.72);padding:10px;box-shadow:inset 0 0 22px rgba(0,0,0,.18)}.aw-card:hover{border-color:rgba(0,245,154,.34)}.aw-btn,.aw-btn:visited,button.aw-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid rgba(0,245,154,.30);border-radius:7px;padding:8px 10px;background:linear-gradient(180deg,rgba(10,48,37,.9),rgba(4,25,19,.9));color:var(--aw-text);text-decoration:none;cursor:pointer;transition:.16s}.aw-btn:hover{color:var(--aw-green);border-color:var(--aw-green);box-shadow:0 0 16px rgba(0,245,154,.12)}.aw-btn.primary{border-color:rgba(0,245,154,.56);color:var(--aw-green);background:linear-gradient(180deg,rgba(0,100,70,.35),rgba(5,35,27,.92))}.aw-btn.blue{border-color:rgba(37,223,255,.45);color:var(--aw-cyan)}.aw-btn.danger{border-color:rgba(255,75,95,.45);color:#ff98a4;background:rgba(70,12,20,.44)}.aw-btn:disabled{opacity:.35;cursor:not-allowed}.aw-actions,.aw-row,.aw-tabs{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.aw-right{margin-left:auto}.aw-muted{color:var(--aw-muted)}.aw-green{color:var(--aw-green)}.aw-cyan{color:var(--aw-cyan)}.aw-red{color:var(--aw-red)}.aw-amber{color:var(--aw-amber)}.aw-kv{display:inline-flex;border:1px solid rgba(0,245,154,.13);border-radius:6px;padding:4px 6px;background:rgba(1,8,7,.68);color:#87bca8;font-size:10px;word-break:break-word}.aw-chip{display:inline-flex;border:1px solid rgba(37,223,255,.14);border-radius:6px;padding:4px 6px;color:#9acfe0;background:rgba(0,22,30,.35);font-size:10px}.aw-empty{padding:22px;text-align:center;color:var(--aw-muted)}.aw-pre,pre.aw-pre{white-space:pre-wrap;word-break:break-word;margin:0;background:#010605;border:1px solid rgba(0,245,154,.15);border-radius:7px;padding:9px;color:#7fffc5;max-height:280px;overflow:auto;font-size:11px}.aw-modal{display:none;position:fixed;inset:0;z-index:50;background:rgba(0,3,2,.82);backdrop-filter:blur(5px);padding:20px;align-items:center;justify-content:center}.aw-modal.open{display:flex}.aw-modal-card{width:min(980px,100%);max-height:92vh;overflow:auto;background:#03110d;border:1px solid rgba(0,245,154,.42);border-radius:10px;box-shadow:0 28px 90px #000}.aw-modal-head{position:sticky;top:0;z-index:2;display:flex;gap:8px;align-items:center;padding:11px 12px;background:#03110d;border-bottom:1px solid rgba(0,245,154,.22)}.aw-toast{position:fixed;right:18px;bottom:18px;z-index:100;display:none;max-width:430px;padding:11px 13px;border:1px solid rgba(0,245,154,.5);border-radius:8px;background:#073023;color:#dfffee;box-shadow:0 16px 45px #000}.aw-toast.error{border-color:rgba(255,75,95,.6);background:#351018;color:#ffc0c8}@media(max-width:900px){.aw-app{grid-template-columns:1fr}.aw-sidebar{position:relative;height:auto;border-right:0;border-bottom:1px solid rgba(0,245,154,.2)}.aw-nav{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}.aw-sidebar-foot{display:none}.aw-main{padding:10px}.aw-topbar{padding-left:0;padding-right:0}.aw-wordmark{font-size:15px}}@media(max-width:600px){.aw-nav{grid-template-columns:repeat(2,minmax(0,1fr))}.aw-search{display:none}.aw-topstatus{margin-left:0}.aw-logo{width:48px;height:48px}}
"""
